or	virtual ~CParseTokenAutoList();		// Destructor};//========================================================================================// CParseToken//========================================================================================class CParseToken// CParseToken is the base class for tokens created in the parsing process.{	friend class CParseTokenList;public:	// Types	typedef CConstTextPtr::size_type		size_type;	typedef CConstTextPtr::difference_type	difference_type;	// Construct and destroy	CParseToken(const CParseTerm* term, const CTextBuffer& buffer);		// Construct a top level token that refers to a text buffer. 	CParseToken(const CParseTerm* term, const CConstTextToken& text);		// Construct a top level token that refers to a range of text. 	virtual ~CParseToken();	// Accessors	const CParseTerm* GetTerm() const	{ return fParseTerm; }	CConstTextToken GetText() const		{ return fText; }		std::string GetString() const;		// Gets a copy of the text as a string. 	// Notification		IDType GetIdentifier() const;		// Retrieve the identifier for this token.	// Sub-token management.	void AddSubToken(CParseToken* token);		// Adds the token as a subtoken, unless its throw away flag is set, in which		// case it is deleted. 		void RemoveSubToken(CParseToken* token);		// Remove the given token but do not delete it.		bool ThrowAway() const { return fThrowAway; }		// Return true if this token should not be processed any further.			virtual void Added();		// Gives a token an opportunity to do something when it's been added to the tree. 	// Dataprotected:	CConstTextToken		fText;			// The text for this token. 	const CParseTerm*	fParseTerm;		// The parse term which created this token.	CParseToken*		fParent;		// The token which contains this one.	CParseTokenAutoList	fTokens;		// A list of our sub-tokens.	bool				fThrowAway;		// Set to true and this token will be deleted										// instead of added to the tree. };#endif // __CParseToken__